  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Calculates the final price for a booking made by the given customer at the specified booking time, applying a 20 percent discount when the customer holds a DISCOUNTS award and the booking is made at least 24 hours before the trip's departure.
   * Algorithm:
   *   1. If customer == null OR bookingTime == null OR bookingTime is empty, return this.price.
   *   2. If customer.membershipPackage == null OR !customer.membershipPackage.hasAward(Award.DISCOUNTS), return this.price.
   *   3. Parse bookingTime and this.departureTime as "yyyy-MM-dd HH:mm".
   *   4. Compute duration = departureTime - bookingTime in minutes/hours.
   *   5. If duration < 24 hours (i.e., strictly less than 24*60 minutes), return this.price.
   *   6. Otherwise, discounted = this.price * 0.8.
   *   7. Round discounted to one decimal place (half-up rounding).
   *   8. Return discounted.
   * Related Features: price, departureTime
   * Related Classes: Customer, MembershipPackage, Award
   * Input:
   *   - customer : Customer — the customer making the booking; must be non-null with a valid membership package for the discount to apply.
   *   - bookingTime : String — the booking creation time in "yyyy-MM-dd HH:mm" format.
   * Output: double — the final price; either the original this.price (no discount) or this.price * 0.8 rounded to one decimal place (discount applied).
   * Pre-condition: this.price must be set; bookingTime must be a valid datetime string in "yyyy-MM-dd HH:mm"; this.departureTime must be a valid datetime string in "yyyy-MM-dd HH:mm".
   * Post-condition: The trip's state is unchanged; only a numeric price value is returned.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || bookingTime == null || bookingTime.isEmpty())
    {
      return getPrice();
    }
    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.DISCOUNTS))
    {
      return getPrice();
    }
    try
    {
      SimpleDateFormat format = new SimpleDateFormat("yyyy-MM-dd HH:mm");
      Date bookingDateTime = format.parse(bookingTime);
      Date departureDateTime = format.parse(getDepartureTime());
      long durationMillis = departureDateTime.getTime() - bookingDateTime.getTime();
      long durationMinutes = durationMillis / (60 * 1000);
      if (durationMinutes < 24 * 60)
      {
        return getPrice();
      }
      double discounted = getPrice() * 0.8;
      BigDecimal rounded = new BigDecimal(discounted).setScale(1, RoundingMode.HALF_UP);
      return rounded.doubleValue();
    }
    catch (ParseException e)
    {
      return getPrice();
    }
  }

